{"thought":"I have the spec and CONTRIBUTING.md. The implementation is straightforward Levenshtein distance. I'll implement it now while waiting for @eng-80's edge-case notes. Let me write the implementation and unit tests. I'll use the classic DP approach with two rows for efficiency.","action":{"tool":"write_file","args":{"path":"src/textkit/edit_distance.py","content":"from __future__ import annotations


def edit_distance(a: str, b: str) -> int:
    """
    Return the edit distance between `a` and `b`: the minimum number of
    single-character edits needed to turn `a` into `b`.

    Inserting, deleting or substituting one character each cost 1. The comparison
    is case-sensitive, and the distance is symmetric:
    edit_distance(a, b) == edit_distance(b, a). Used by search suggestions for
    typo tolerance.

    Examples:
        edit_distance("kitten", "sitting") == 3
        edit_distance("", "abc") == 3
    """
    if not a and not b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Ensure b is the shorter string to minimise memory usage.
    if len(a) < len(b):
        a, b = b, a

    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        curr = [i] + [0] * len(b)
        for j, cb in enumerate(b, start=1):
            cost = 0 if ca == cb else 1
            curr[j] = min(
                prev[j] + 1,       # deletion
                curr[j - 1] + 1,   # insertion
                prev[j - 1] + cost # substitution / match
            )
        prev = curr
    return prev[len(b)]
"}},"messages":[]}

